use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn main () -> Result < () > { let cli = Cli :: parse () ; if cli . verbose { println ! ("Auditing dependencies in {}" , cli . output_dir . display ()) ; } let mut available_submodules = HashMap :: new () ; for entry in WalkDir :: new ("submodules") . max_depth (2) { let entry = entry ? ; if entry . file_name () == "Cargo.toml" { if let Some (parent) = entry . path () . parent () { if let Some (crate_name) = parent . file_name () . and_then (| n | n . to_str ()) { available_submodules . insert (crate_name . to_string () , parent . to_path_buf ()) ; } } } } if cli . verbose { println ! ("Found {} available submodules" , available_submodules . len ()) ; } let mut all_issues = Vec :: new () ; let mut workspace_deps = HashMap :: new () ; let workspace_cargo = cli . output_dir . join ("Cargo.toml") ; if workspace_cargo . exists () { let content = fs :: read_to_string (& workspace_cargo) ? ; let toml : Value = toml :: from_str (& content) ? ; if let Some (workspace) = toml . get ("workspace") { if let Some (deps) = workspace . get ("dependencies") { if let Value :: Table (deps_table) = deps { for (dep_name , dep_spec) in deps_table { workspace_deps . insert (dep_name . clone () , dep_spec . clone ()) ; if let Value :: Table (spec_table) = dep_spec { if let Some (path_val) = spec_table . get ("path") { if let Value :: String (path_str) = path_val { if ! path_str . starts_with ("../submodules/") { all_issues . push (DependencyIssue { crate_name : "workspace" . to_string () , dep_name : dep_name . clone () , issue_type : IssueType :: NotLocalPath , current_spec : path_str . clone () , suggested_fix : available_submodules . get (dep_name) . map (| p | format ! ("../submodules/{}" , dep_name)) , }) ; } } } else if ! spec_table . contains_key ("path") { if available_submodules . contains_key (dep_name) { all_issues . push (DependencyIssue { crate_name : "workspace" . to_string () , dep_name : dep_name . clone () , issue_type : IssueType :: MissingSubmodule , current_spec : format ! ("{:?}" , dep_spec) , suggested_fix : Some (format ! ("../submodules/{}" , dep_name)) , }) ; } } } } } } } } for entry in WalkDir :: new (& cli . output_dir) . max_depth (1) { let entry = entry ? ; let path = entry . path () ; if path . is_dir () && path . file_name () . and_then (| n | n . to_str ()) . map (| s | s . starts_with ("wrapped-")) . unwrap_or (false) { let cargo_toml = path . join ("Cargo.toml") ; if cargo_toml . exists () { let crate_name = path . file_name () . unwrap () . to_str () . unwrap () ; audit_crate_dependencies (& cargo_toml , crate_name , & workspace_deps , & available_submodules , & mut all_issues) ? ; } } } if all_issues . is_empty () { println ! ("✅ All dependencies are properly configured") ; return Ok (()) ; } println ! ("❌ Found {} dependency issues:" , all_issues . len ()) ; for issue in & all_issues { match issue . issue_type { IssueType :: MissingFromWorkspace => { println ! ("  {} -> {}: Missing from workspace dependencies" , issue . crate_name , issue . dep_name) ; } IssueType :: NotLocalPath => { println ! ("  {} -> {}: Not pointing to local submodule ({})" , issue . crate_name , issue . dep_name , issue . current_spec) ; } IssueType :: WorkspaceInheritance => { println ! ("  {} -> {}: Using workspace inheritance without workspace context" , issue . crate_name , issue . dep_name) ; } IssueType :: MissingSubmodule => { println ! ("  {} -> {}: External dep but submodule available" , issue . crate_name , issue . dep_name) ; } } if let Some (fix) = & issue . suggested_fix { println ! ("    Suggested: {}" , fix) ; } } if cli . fix { println ! ("\n🔧 Applying fixes...") ; apply_fixes (& all_issues , & cli . output_dir) ? ; println ! ("✅ Fixes applied") ; } else { println ! ("\nRun with --fix to automatically apply suggested fixes") ; } Ok (()) }